def clean(df):
    df = df.drop_duplicates()
    df['Category'] = df['Category'].str.strip().replace({' Electronics': 'Electronics', ' Furniture': 'Furniture', 'Office Supplies ': 'Office Supplies'})
    df['Price'] = df['Price'].str.replace('$', '').astype(float)
    df = df[df['Quantity'] >= 0]
    return df

def answer(df):
    counts = df['Category'].value_counts().to_dict()
